const thenable: any = { then(res: (v: number) => void) { res(42); } };
const failing: any = { then(res: any, rej: any) { rej(new Error('boom')); } };
async function viaAsync(): Promise<any> { return thenable; }
async function main(): Promise<void> {
  console.log(await thenable);
  console.log(await viaAsync());
  console.log(await Promise.resolve(thenable));
  try { await failing; } catch (e: any) { console.log('caught', e.message); }
  const plain: any = { a: 1 };
  const same = await plain;
  same.a = 2;
  console.log(plain.a);
}
